"""Record current Rootstock host reading and the queued-input counterexample."""
from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,subprocess
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[2];NAME='rootstock_host_review_receipt.json'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
load=lambda n:json.loads((HERE/n).read_text(encoding='utf-8-sig'))
def git(*a):return subprocess.check_output(['git',*a],cwd=ROOT,text=True).strip()
def save(n,v):(HERE/n).write_text(json.dumps(v,indent=2)+'\n',encoding='utf-8')
assert not (HERE/NAME).exists()
old=load('workspace_rootstock_review_receipt.json');head=git('rev-parse','HEAD');assert head==old['basis_commit']
guards={**old['preserved_production_and_test_hashes'],**old['source_sha256']};assert len(guards)==1579
assert all(sha(ROOT/n)==h for n,h in guards.items()) and all(sha(HERE/n)==h for n,h in old['evidence_sha256'].items())
doc=ROOT/old['document']['path'];prefix=doc.read_bytes();assert sha(doc)==old['document']['sha256']
assert all(sha(ROOT/n)==h for n,h in old['shared_working_file_sha256'].items() if n!=old['document']['path'])
index=Path(git('rev-parse','--git-path','index'));index=index if index.is_absolute() else ROOT/index;index_hash=sha(index)
inv,cov=load('source_inventory.json'),load('read_coverage.json');assert inv['commit']==head and load('pending_read.json')==[]
names=['embedding/iced.rs','embedding/iced_input.rs','embedding/input.rs','embedding/tests.rs','files.rs','frame.rs','host.rs','input.rs','input/trace.rs','lib.rs','mount_probe_tests.rs','multi_host.rs']
whole=['crates/cambium/cambium-rootstock/src/'+n for n in names]
assert len(whole)==12 and sum(inv['files'][n]['chars'] for n in whole)==269372
assert all(cov[n]['sha256']==inv['files'][n]['sha256'] and cov[n]['through']==inv['files'][n]['chars'] and sha(ROOT/n)==inv['files'][n]['sha256'] for n in whole)
stats=json.loads(subprocess.check_output(['python',str(HERE/'read_coverage.py'),'status'],cwd=ROOT))
assert stats['complete_files']==2061 and stats['read_chars']==24843571 and not stats['changed_since_inventory'] and not stats['pending_chunks']
probe=load('rootstock_queue_probe_receipt.json')
assert probe['build_exits']==[0,0,0] and probe['run_exit']==0 and probe['checks']==3
assert probe['generated_output_removed'] and all(not Path(o['path']).exists() for o in probe['removed_outputs'])
assert all(sha(ROOT/n)==h for n,h in probe['source_sha256'].items()) and all(sha(Path(v['path']))==v['sha256'] for v in probe['libraries'].values())
notes,authority=load('review_notes.json'),load('authority_map.json');assert notes['findings'][-1]['id']=='Q305' and authority['entries'][-1]['id']=='A773'
finding={'id':'Q306','title':'Hook-queued pointer events recursively overtake events already waiting in the host queue',
 'source':'crates/cambium/cambium-rootstock/src/host.rs:1751,1851,1900; crates/cambium/cambium-rootstock/src/input.rs:645',
 'status':'verified original current toolkit and Rootstock over retained exact suppliers',
 'evidence':'drain_pointer takes the current pending queue, but each delivered event can call after_dispatch -> with_ctx -> apply_pending -> drain_pointer again. An after_dispatch hook that queues another event therefore recursively drains it before the next event in the already-taken batch. The original current Host probe queues zoom-in A and zoom-out B. Without hook-enqueued work the hook observes [1.1,1.0]. When A queues zoom-in C, one outer drain observes [1.1,1.25,1.1], demonstrating A,C,B ordering, with C already consumed instead of pending for a later drain. This contradicts the source promise that the queue is ordered and hook-enqueued work lands on the next drain rather than looping. The fixture bounds itself to one extra event; no unbounded loop, stack overflow, native event source or product failure was executed.',
 'verification':NAME,'diagnostics':['rootstock_queue_probe_receipt.json'],
 'repair_triage':{'disposition':'documented; production unchanged under active read-only audit goal','reason':'Track an active queue-drain turn and defer nested drains until that turn ends, preserving the chosen FIFO/next-turn contract. Exercise already-queued events plus hook-enqueued pointer and wheel work. Do not create another replay dispatcher or rely on every application hook to suppress recursion.'}}
notes['findings'].append(finding)
rows=[
 ('Embedding adapters share rendering but duplicate adapter lifetime state','Egui and Iced both use embedding::Gpu, while their callback/primitive adapters independently hold epoch, generation, appearance, disposal and error state.', ['embedding/iced.rs','embedding/iced_input.rs','embedding/input.rs','embedding/tests.rs','embedding/egui.rs'], 'Iced prepares placement admission separately then renders with the caller encoder; egui prepares GPU resources then paints in a toolkit pass. Input adapters independently translate toolkit key/text/IME/pointer events into OwnerInput and reject unsupported envelopes. Shared ScrollUnits is real caller-owned wheel policy. Existing source tests cover focus/capture/clip/coordinates, source facts, lifecycle/timers and IME units; optional adapters were read rather than built/executed this pass.'),
 ('Host options, runtime state and hook contexts','Host initializes runtime zoom from options; later UI state and product hooks use the same host-owned fields.', ['host.rs'], 'AppCtx construction is repeated in frame preparation, with_ctx, presentation observation and close negotiation. It is plumbing around one runner/shared resources, not four copies of application truth. Presentation observation deliberately does not consume zoom edges. Window frame compatibility decorations still participates alongside the named frame policy; source comments name the remaining migration consumer.'),
 ('Deferred self-input and native input share the actual Host path','Queued HostPointer events call the normal pointer/wheel methods, but nested hook drains violate the promised ordering.', ['host.rs','input.rs'], 'Q306 uses original current Host and hook implementations, without a parallel simulator. Logical wheel input and Ctrl zoom are enough to demonstrate A,C,B reordering without layout/GPU. The ordinary input implementation is shared, but scheduling/reentrancy still needs one explicit owner.'),
 ('Logical text editing and visual caret correction are distinct authorities','Toolkit logical moves precede the host visual caret default, which recomputes from a pre-dispatch selection snapshot.', ['input.rs','lib.rs','frame.rs'], 'The host applies visual movement only when default was not prevented and focus still names the same field; product key interception and host zoom/held-Tab policy can run before the tree by explicit design. Click/drag and IME use the product-supplied FocusedTextSlot. The broad view-first comment has these explicit host exceptions; there is no universal toolkit-only key authority.'),
 ('Asynchronous file responses bind only a DOM node','FileAnswer retains NodeId, an answer queue and a wake handle; deliver_files resolves the current runner file route for that node.', ['files.rs','host.rs'], 'The host delegates chooser policy and answers missing choosers with cancellation. The envelope has no request generation, source binding or captured handler identity. Current source trace establishes that limitation, not a verified deployed wrong-owner import. Trace actual retained/replaced consumers before turning the earlier response-binding follow-up into a finding.'),
 ('Frame preparation, resources and success identities','The frame path delegates presentation/readback, while producer remapping refusal clears the current presentation and resolves armed captures as errors.', ['frame.rs','host.rs','lib.rs'], 'Relayout uses one OwnedLayout, carries scroll planes during ordinary rebuilds and composes leaves from shared registries. Captured paint envelopes are CPU commands with GPU references, not pixel readbacks. PresentedFrame explicitly certifies queue submission rather than compositor visibility. Leaf fragment IDs are registered/updated, but the emitter passes no fragment lookup; the host documents this unconsumed staging layer. No performance benefit is established by its existence.'),
 ('Shadow mount probes use a different stylesheet path from production','AC7 mount tests explicitly discover DOM stylesheet resources and use cambium_resources instead of OwnedLayout::new.', ['mount_probe_tests.rs'], 'The probe itself states production OwnedLayout uses document-scope sheets and ignores DOM style elements. Shadow boundary/withdrawal controls are meaningful within that custom pipeline; they cannot establish production guest stylesheet isolation. Tests also show the parent-only withdrawal walk cannot cross a shadow root when the retained owner is inside it. No source test was rerun this pass.'),
 ('Multi-window turns lend one runner and shared resources','MultiHost really shares the application runner, hooks and AppShared and calls the same per-window Host pipeline.', ['multi_host.rs'], 'MutationRouter drains one document and fans moves to old/new parents, conservatively sending unplaceable changes to all windows. with_window manually takes, swaps, invokes and returns shared custody without an unwind guard. Closing retires orphan producers by live ancestry. Fault/reentrant turn handling and shared disposal remain to inspect; one shared app state does not repair the Q301 per-projection view nursery gap.')
]
entries=[]
for i,(domain,claim,paths,assessment) in enumerate(rows):
 entries.append({'id':f'A{774+i}','domain':domain,'claim':claim,'implementations':['crates/cambium/cambium-rootstock/src/'+n for n in paths],'assessment':assessment,'state':'current source read; focused original host queue check only','verification':NAME})
authority['entries'].extend(entries)
notes.setdefault('review_followups',[]).extend([
 {'verification':NAME,'area':'File response binding current host trace','detail':'Host FileAnswer/deliver_files bind only NodeId and resolve current routing, without request/source/handler generation. Continue browser/native chooser and real retained-view consumers before asserting a deployed stale import. No file chooser or owner write was executed.'},
 {'verification':NAME,'area':'Forest turn unwind custody','detail':'MultiHost::with_window moves shared tree/resources/hooks into the selected window and restores them after f returns without an unwind guard. Inspect current caller panic boundaries and tests; no fault-injection or lost-state claim was executed.'},
 {'verification':NAME,'area':'Unconsumed retained leaf fragments','detail':'sync_leaf_fragments registers and refreshes renderer fragment IDs, while emit_paint_list always supplies no fragment lookup. The host explicitly documents this staging path. Inspect feature/callsite and retained-resource costs before claiming a live performance regression.'}
])
next_read={'path':'crates/cambium/cambium-rootstock/src/multi_host_tests.rs','start':0,'reason':'Read multi-host tests and retained OwnedLayout, then producer/presentation/recovery machinery, native/web adapters and every remaining Mere source.'}
notes['current_area']='Rootstock embedding input/tests, host/frame/input, accessibility vocabulary and multi-window custody read'
notes['next_area']=next_read['reason']
notes['checkpoint']={'classification':'progress','classification_of_previous_turn':'progress','goal_status':'active; full source incomplete','coverage':stats,'finding_count':len(notes['findings']),'authority_entries':len(authority['entries']),'new_receipts':[NAME,'rootstock_queue_probe_receipt.json'],'audit_authored_production_edits_this_turn':False,'next_read':next_read,'pending_verification':None,'diagnostic_outcomes':'Three focused queue checks pass using fresh original current Cambium and Rootstock over retained exact suppliers. Optional embedding/native/GPU source remains unexecuted.'}
diff=subprocess.run(['git','diff','--check'],cwd=ROOT,capture_output=True,text=True);assert diff.returncode==0
with (HERE/'rootstock_host_diff_check.txt').open('x',encoding='utf-8') as f:f.write(diff.stdout+diff.stderr)
evidence=['record_rootstock_host_review.py','rootstock_host_diff_check.txt','rootstock_queue_probe.rs','run_rootstock_queue_probe.py','rootstock_queue_probe_receipt.json','rootstock_queue_probe_compile_0.log','rootstock_queue_probe_compile_1.log','rootstock_queue_probe_compile_2.log','rootstock_queue_probe_output.log']
addition=f'''

### Rootstock input scheduling and host boundaries, 2026-10-17

Twelve more Rootstock files / 269,372 characters are fully read, covering remaining embedding adapters/tests, file responses, frame/host/input code, public vocabulary/accessibility projection, shadow mount probes and multi-window turns. Coverage is now {stats['complete_files']:,}/{stats['total_files']:,} files and {stats['read_chars']:,}/{stats['total_chars']:,} characters at unchanged HEAD {head}, without stale hashes or pending chunks. Full-source review remains incomplete.

Q306 verifies misleading deferred-input claims. drain_pointer takes the queued batch, but each event can run after_dispatch -> with_ctx -> apply_pending -> drain_pointer recursively. Queue A=zoom in, B=zoom out: the control observes zooms [1.1, 1.0]. If A's hook queues C=zoom in, one outer drain observes [1.1, 1.25, 1.1], proving A,C,B delivery with C already consumed. The source instead promises ordered delivery and callback events deferred to the next drain rather than looping. The fixture bounds itself to one added event: no unbounded recursion/stack overflow or native product failure is claimed. The [checkpoint](../../../support/receipts/authority-success-audit/{NAME}) binds three passing checks through fresh original current Cambium and Rootstock compiled over 22 hash-bound retained supplier libraries. All generated rlib/executable/PDB outputs were recorded and removed. This is not a fresh whole-current Cargo supplier graph or native/GPU gate.

A774-A781 distinguish shared rendering from repeated toolkit adapter lifetime wrappers, options from one runtime state, actual Host input reuse from broken queue scheduling, logical edits from visual caret correction, node-only file responses from request authority, frame/capture identities, custom shadow probes from production stylesheet paths, and genuinely shared multi-window custody. File-response source has no request/source/handler generation, but no wrong-owner import is promoted without a supported consumer trace. MultiHost restores borrowed shared custody only on ordinary return; unwind/caller boundaries remain unverified. Producer and presentation/recovery modules are still to read.

The host explicitly documents that retained leaf fragments are registered/refreshed but not placed by paint emission; this staging layer is not a demonstrated performance feature. Shadow mount tests explicitly bypass OwnedLayout's production document-scope sheet path with resource-aware styles: their scoped test results must not be sold as production guest isolation. PresentedFrame honestly certifies queue submission, not compositor visibility; paint-envelope capture is CPU commands plus GPU references, not captured pixels. Optional Iced/egui adapters and source tests were read, not executed here.

Production/shared WIP remain byte-preserved, prior audit document text is an exact prefix and the index is unchanged. No branch, worktree, isolated target or Cargo home was created. Continue with multi_host_tests.rs and OwnedLayout, then remaining host machinery and all other unread Mere code.
'''
doc.write_bytes(prefix+addition.encode('utf-8'));save('review_notes.json',notes);save('authority_map.json',authority)
