receipt={'date_utc':datetime.now(timezone.utc).isoformat(),'basis_commit':head,'kind':'Rootstock input scheduling and host boundary source review; full repository incomplete','prior_receipt':{'path':'workspace_rootstock_review_receipt.json','sha256':sha(HERE/'workspace_rootstock_review_receipt.json')},'coverage':stats,'whole_current_files':whole,'source_sha256':{n:sha(ROOT/n) for n in whole},'preserved_production_and_test_hashes':guards,'shared_working_file_sha256':old['shared_working_file_sha256'],'new_findings':['Q306'],'authority_entries':[e['id'] for e in entries],'audit_authored_production_edits_this_pass':False,'diagnostics':{'rootstock_queue_probe_receipt.json':{'build_exits':[0,0,0],'run_exit':0,'checks':3}},'pending_verification':None,'next_read':next_read,'document':{'path':old['document']['path'],'sha256':sha(doc),'preserved_prefix_bytes':len(prefix),'preserved_prefix_sha256':hashlib.sha256(prefix).hexdigest()},'evidence_sha256':{n:sha(HERE/n) for n in evidence},'git_index_sha256':index_hash,'retained_isolation':[],'receipt_budget':{'cap_bytes':100_000_000,'retained_bytes_before_receipt':budget},'limits':'Fresh current Cambium/Rootstock without optional features over retained exact suppliers; no fresh whole-current supplier graph, GPU/native event loop, embedding optional feature, persistence or assistive technology acceptance.'}
save(NAME,receipt)
